-- Read-only native250 authority and schema checks.
BEGIN READ ONLY;SET LOCAL ROLE celebix_saas_owner;
DO $functions$BEGIN
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting250_commission_guard()') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='daf5572c4d06cf651eea616751e55c77d9d705fcbe4196c9932b12f82e9a2424' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='v' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.accounting250_commission_guard()';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.accounting_commissions_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,jsonb)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='c3bda68f3696db6b7fd83d049177508e5991ebe643430faa3bb19824f573bda0' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.accounting_commissions_read(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,jsonb)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_list_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='3f360ee77b9f085e5222a7ab884ff2b105e1edcf3c8ee6174b2688f7d9773782' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.in_store_sales_list_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_recover_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='a19f7505e7e4744828004548859da49ccd36e3f61a363ed8713c4a12c02aa2da' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.in_store_sales_recover_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_sales_set_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,boolean,uuid[],integer,boolean,boolean,boolean,boolean,boolean,integer)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='3dc299f8d88aab2adf58f00a1f0010195f7f5ac5385b4442776c03e0f90cdaa9' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner,celebix_saas_app=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='v' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.in_store_sales_set_staff_v6(uuid,uuid,uuid,uuid,text,bigint,timestamp with time zone,uuid,text,uuid,bigint,boolean,uuid[],integer,boolean,boolean,boolean,boolean,boolean,integer)';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_proc p WHERE p.oid=to_regprocedure('saas.in_store_staff_projection_v6(uuid,uuid)') AND encode(sha256(convert_to(pg_get_functiondef(p.oid),'UTF8')),'hex')='4573129253e4f0af8eeb31ca0fcc2b24b23254c60bef1668aa4db75c1f6acfd8' AND p.proowner='celebix_saas_owner'::regrole AND p.proacl='{celebix_saas_owner=X/celebix_saas_owner}'::aclitem[] AND p.proconfig=ARRAY['search_path=pg_catalog, saas']::text[] AND p.prosecdef AND p.provolatile='s' AND NOT p.proisstrict AND p.proparallel='u')THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_DRIFT:%','saas.in_store_staff_projection_v6(uuid,uuid)';END IF;
END $functions$;
DO $schema$BEGIN
 IF(SELECT count(*)FROM pg_proc WHERE pronamespace='saas'::regnamespace AND prokind='f')<>1888 THEN RAISE EXCEPTION 'COMMISSION250_FUNCTION_SCOPE';END IF;
 IF(SELECT count(*)FROM information_schema.columns WHERE table_schema='saas'AND table_name='in_store_staff_grants'AND((column_name='commission_enabled'AND is_nullable='NO'AND column_default='false')OR(column_name='commission_rate_bps'AND is_nullable='NO'AND column_default='0')))<>2 THEN RAISE EXCEPTION 'COMMISSION250_DEFAULTS';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='saas.in_store_staff_grants'::regclass AND conname='in_store_commission250_rate' AND contype='c'AND convalidated)THEN RAISE EXCEPTION 'COMMISSION250_RATE_CONSTRAINT';END IF;
 IF NOT EXISTS(SELECT 1 FROM pg_class WHERE oid='saas.accounting_cashier_commission_sales'::regclass AND relowner='celebix_saas_owner'::regrole AND relrowsecurity AND relforcerowsecurity)OR has_table_privilege('celebix_saas_app','saas.accounting_cashier_commission_sales','SELECT,INSERT,UPDATE,DELETE')THEN RAISE EXCEPTION 'COMMISSION250_PRIVATE_TABLE';END IF;
 IF(SELECT count(*)FROM pg_constraint WHERE conrelid='saas.accounting_cashier_commission_sales'::regclass AND contype='f')<>1 OR NOT EXISTS(SELECT 1 FROM pg_constraint WHERE conrelid='saas.accounting_cashier_commission_sales'::regclass AND contype='f'AND confrelid='saas.stores'::regclass AND confdeltype='c')THEN RAISE EXCEPTION 'COMMISSION250_NO_BUSINESS_FK';END IF;
 IF(SELECT count(*)FROM pg_trigger WHERE NOT tgisinternal AND tgname IN('accounting_commission250_capture','accounting_commission250_immutable')AND tgenabled='O'AND tgfoid='saas.accounting250_commission_guard()'::regprocedure)<>2 OR to_regclass('saas.accounting_commission250_period')IS NULL OR to_regclass('saas.in_store_commission250_creator')IS NULL THEN RAISE EXCEPTION 'COMMISSION250_CAPTURE_SCOPE';END IF;
 IF EXISTS(SELECT 1 FROM saas.accounting249_original_functions WHERE encode(sha256(convert_to(pg_get_functiondef(to_regprocedure(signature)),'UTF8')),'hex')<>published_sha256)THEN RAISE EXCEPTION 'COMMISSION250_PREVIOUS_AUTHORITY';END IF;
 IF saas.built_in_payment_methods_preflight()IS DISTINCT FROM true OR saas.payment_provider_keyed_lifecycle_preflight()IS DISTINCT FROM true OR saas.iyzico_iframe_tenant_activation_runtime_preflight()IS DISTINCT FROM true OR saas.quick_order_hosted_payment_authority_preflight()IS DISTINCT FROM true OR saas.shipping_provider_preflight()IS DISTINCT FROM true THEN RAISE EXCEPTION 'COMMISSION250_PAYMENT_PREFLIGHT';END IF;
END $schema$;ROLLBACK;
